vi.mock('@felinic/ui', async original => ({ ...await original<object>(), toast: { error: api.error, success: api.success } }))
vi.mock('pinia', async original => ({ ...await original<object>(), storeToRefs: (await import('vue')).toRefs }))
const chat = reactive({ fsChangedAt: 0, markFsChanged() {} })
const tabs = reactive({ activeId: null })
vi.mock('@/store/chat-list', () => ({ useChatStore: () => chat }))
vi.mock('@/store/workspace-tabs', () => ({ useWorkspaceTabsStore: () => tabs }))
let tree: FileTreeContext
vi.mock('@/components/file-manager/file-tree.vue', async () => {
  const { inject, h } = await import('vue')
  const { FileTreeKey } = await import('@/components/file-manager/file-tree-context')
  return { default: { setup() { tree = inject(FileTreeKey)!; return () => h('div') } } }
})
const bot = '10000000-0000-4000-8000-000000000001'
const other = '20000000-0000-4000-8000-000000000002'
const props = reactive({ botId: bot, active: true, canWrite: true })
let app: ReturnType<typeof createApp> | undefined
let root: HTMLDivElement
const entries: HandlersFsFileInfo[] = [{ path: '/data/original.txt', name: 'original.txt', isDir: false, size: 7 }]
async function settle() { await nextTick(); await Promise.resolve(); await nextTick() }
async function mount() {
 root = document.createElement('div'); document.body.append(root)
 app = createApp({ render: () => h(FilesPane, props) }).use(createI18n({ legacy: false, locale: 'en', messages: { en } }))
 app.mount(root); await settle()
}
beforeEach(() => { vi.useFakeTimers(); vi.clearAllMocks(); api.list.mockReset(); api.list.mockResolvedValue({ data: { entries } }); props.botId = bot; props.active = true })
afterEach(() => { app?.unmount(); root?.remove(); vi.useRealTimers() })
describe('phone directory activity and original Bot ownership', () => {
 it('does not issue reads while inactive', async () => {
  props.active = false; await mount(); expect(await tree.listDirectory('/data')).toEqual([]); expect(api.list).not.toHaveBeenCalled()
 })
 it('returns current active results for the original Bot and path', async () => {
  await mount(); expect(await tree.listDirectory('/data')).toEqual(entries)
  expect(api.list).toHaveBeenCalledExactlyOnceWith({ path: { bot_id: bot }, query: { path: '/data' }, throwOnError: true })
 })
 it.each(['inactive', 'otherBot'] as const)('discards an in-flight success after %s without changing original entries', async change => {
  let finish!: (value: { data: { entries: HandlersFsFileInfo[] } }) => void
  api.list.mockImplementationOnce(() => new Promise(resolve => { finish = resolve }))
  await mount(); const snapshot = JSON.stringify(entries); const pending = tree.listDirectory('/data/held')
  if (change === 'inactive') props.active = false; else props.botId = other
  await settle(); finish({ data: { entries } }); expect(await pending).toEqual([])
  expect(api.list).toHaveBeenCalledTimes(1); expect(api.error).not.toHaveBeenCalled(); expect(JSON.stringify(entries)).toBe(snapshot)
 })
 it.each(['inactive', 'otherBot'] as const)('does not retry the original path under %s after a transient failure', async change => {
  api.list.mockRejectedValue({ code: 'workspace.unreachable', status: 503 })
  await mount(); const pending = tree.listDirectory('/data/old-only'); await settle(); expect(api.list).toHaveBeenCalledTimes(1)
  if (change === 'inactive') props.active = false; else props.botId = other
  await settle(); await vi.advanceTimersByTimeAsync(500); expect(await pending).toEqual([])
  expect(api.list).toHaveBeenCalledTimes(1); expect(api.error).not.toHaveBeenCalled()
 })
 it('suppresses a stale non-transient rejection instead of showing an error for the new Bot', async () => {
  let reject!: (reason: unknown) => void
  api.list.mockImplementationOnce(() => new Promise((_resolve, fail) => { reject = fail }))
  await mount(); const pending = tree.listDirectory('/data/held'); props.botId = other; await settle(); reject({ code: 'http.forbidden', status: 403 })
  expect(await pending).toEqual([]); expect(api.error).not.toHaveBeenCalled(); expect(api.list).toHaveBeenCalledTimes(1)
 })
 it('retains the existing bounded retry for the same active Bot', async () => {
  api.list.mockRejectedValueOnce({ code: 'workspace.unreachable', status: 503 }).mockRejectedValueOnce({ code: 'workspace.unreachable', status: 503 }).mockResolvedValueOnce({ data: { entries } })
  await mount(); const pending = tree.listDirectory('/data/current'); await settle(); await vi.advanceTimersByTimeAsync(500); await vi.advanceTimersByTimeAsync(1000)
  expect(await pending).toEqual(entries); expect(api.list).toHaveBeenCalledTimes(3)
  for (const [request] of api.list.mock.calls) expect(request).toEqual({ path: { bot_id: bot }, query: { path: '/data/current' }, throwOnError: true })
  expect(api.error).not.toHaveBeenCalled()
 })
 it('still reports a current active permission failure once', async () => {
  api.list.mockRejectedValue({ code: 'http.forbidden', status: 403 }); await mount(); expect(await tree.listDirectory('/data/current')).toEqual([])
  expect(api.list).toHaveBeenCalledTimes(1); expect(api.error).toHaveBeenCalledTimes(1)
 })
})
